folders=['01_root_elephant','02_flow_otter','03_will_tiger','04_warmth_deer','05_voice_bird','06_sight_owl','07_light_lotus']
def zpath(i,pose='01_idle',size=480):
    return f'{B}/img/zork/{size}/{folders[i]}/zork_{folders[i]}_{pose}.webp'
def image(src,alt,cls='',eager=False):
    return f'<img class="{cls}" src="{src}" alt="{alt}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
def button(href,text,cls=''):return f'<a class="rh-btn {cls}" href="{href}">{text}<span aria-hidden="true">↗</span></a>'
